t.script:
// Get plan limits from template (set before CDATA)
const maxWebsites = ;
const maxVideos = ;

            // Function to show limit notification
            function showLimitNotification(message) {
              // Remove existing notification if any
              const existing = document.getElementById('limit-notification');
              if (existing) {
                existing.remove();
              }
              
              // Create notification element
              const notification = document.createElement('div');
              notification.id = 'limit-notification';
              notification.className = 'limit-notification';
              notification.innerHTML = 
                '<div class="notification-content">' +
                  '<i class="fa fa-exclamation-triangle notification-icon"></i>' +
                  '<div class="notification-text">' +
                    '<div class="notification-title">Plan Limit Reached</div>' +
                    '<div class="notification-message">' + message + '</div>' +
                  '</div>' +
                  '<button type="button" class="notification-close" onclick="this.parentElement.parentElement.remove()">&times;</button>' +
                '</div>';
              
              document.body.appendChild(notification);
              
              // Show with animation
              setTimeout(function() {
                notification.classList.add('show');
              }, 10);
              
              // Auto-hide after 5 seconds
              setTimeout(function() {
                notification.classList.remove('show');
                setTimeout(function() {
                  if (notification.parentElement) {
                    notification.remove();
                  }
                }, 300);
              }, 5000);
            }
            
            document.addEventListener("DOMContentLoaded", function () {
          // Form state management
          let currentStep = 1;
          const totalSteps = 8;
          const form = document.getElementById('vcard-form');
          const progressBar = document.getElementById('form-progress');
          const submitBtn = document.getElementById('submit-btn');
          
          // Initialize form
          loadFormData(); // Load any saved data first
          showStep(1);
          updateProgress();
          
          // Clear saved data on successful form submission
          form.addEventListener('submit', function() {
            clearFormData();
          });
          
          // Color input handlers
              const primaryColorInput = document.getElementById('primary_color');
              const secondaryColorInput = document.getElementById('secondary_color');
              
              if (primaryColorInput) {
                primaryColorInput.addEventListener('input', function() {
                  const selectedTemplate = document.getElementById('selected_template') ? document.getElementById('selected_template').value || 'modern' : 'modern';
                  if (typeof updateTemplatePreview === 'function') {
                    updateTemplatePreview(selectedTemplate);
                  }
                });
                primaryColorInput.addEventListener('change', function() {
                  const selectedTemplate = document.getElementById('selected_template') ? document.getElementById('selected_template').value || 'modern' : 'modern';
                  if (typeof updateTemplatePreview === 'function') {
                    updateTemplatePreview(selectedTemplate);
                  }
                });
              }
              
              if (secondaryColorInput) {
                secondaryColorInput.addEventListener('input', function() {
                  const selectedTemplate = document.getElementById('selected_template') ? document.getElementById('selected_template').value || 'modern' : 'modern';
                  if (typeof updateTemplatePreview === 'function') {
                    updateTemplatePreview(selectedTemplate);
                  }
                });
                secondaryColorInput.addEventListener('change', function() {
                  const selectedTemplate = document.getElementById('selected_template') ? document.getElementById('selected_template').value || 'modern' : 'modern';
                  if (typeof updateTemplatePreview === 'function') {
                    updateTemplatePreview(selectedTemplate);
                  }
                });
              }
          
          // Lead form toggle functionality
              const showFormYes = document.getElementById("show_form_yes");
              const extraFields = document.getElementById("lead_extra_fields");
              const mailingListField = document.querySelector('input[name="mailing_list_name"]');
              
              const toggleLeadFields = () => {
                const isEnabled = showFormYes && showFormYes.checked;
                extraFields.style.display = isEnabled ? "block" : "none";
                if (mailingListField) {
                  if (isEnabled) {
                    mailingListField.setAttribute('required', 'required');
                  } else {
                    mailingListField.removeAttribute('required');
                    mailingListField.classList.remove('is-invalid', 'is-valid');
                  }
                }
              };
              
              if (showFormYes) {
                showFormYes.addEventListener("change", toggleLeadFields);
              }
              
              // Instant leadback toggle
              const leadbackYes = document.getElementById("enable_instant_leadback_yes");
              const leadbackEmailContainer = document.getElementById("leadback_email_container");
              const leadbackMessagingContainer = document.getElementById("leadback_messaging_container");
              const leadbackEmailYes = document.getElementById("leadback_send_email_yes");
              const leadbackMessagingYes = document.getElementById("leadback_enable_messaging_yes");
              const messagingChannelsContainer = document.getElementById("messaging_channels_container");
              
              if (leadbackYes) {
                leadbackYes.addEventListener("change", function() {
                  const isEnabled = this.checked;
                  
                  // Show/hide email and messaging containers
                  if (leadbackEmailContainer) {
                    leadbackEmailContainer.style.display = isEnabled ? 'block' : 'none';
                  }
                  if (leadbackMessagingContainer) {
                    leadbackMessagingContainer.style.display = isEnabled ? 'block' : 'none';
                  }
                  
                  // If disabled, uncheck the sub-options
                  if (!isEnabled) {
                    if (leadbackEmailYes) leadbackEmailYes.checked = false;
                    if (leadbackMessagingYes) {
                      leadbackMessagingYes.checked = false;
                      if (messagingChannelsContainer) {
                        messagingChannelsContainer.style.display = 'none';
                      }
                    }
                  }
                });
              }
              
              // Messaging checkbox toggle
              if (leadbackMessagingYes) {
                leadbackMessagingYes.addEventListener("change", function() {
                  if (messagingChannelsContainer) {
                    messagingChannelsContainer.style.display = this.checked ? 'block' : 'none';
                  }
                });
              }

              // Websites functionality
              const websitesContainer = document.getElementById("websites-container");
              const addWebsiteBtn = document.getElementById("add-website");
              
              // Function to get current secondary color
              const getSecondaryColor = function() {
                return secondaryColorInput ? secondaryColorInput.value || '#4C75A3' : '#4C75A3';
              };
              
              // Update existing website color inputs when secondary color changes
              if (secondaryColorInput) {
                secondaryColorInput.addEventListener('change', function() {
                  // Update all website color inputs that haven't been manually changed
                  const websiteColorInputs = document.querySelectorAll('input[name="website_color[]"]');
                  const newSecondaryColor = this.value;
                  websiteColorInputs.forEach(function(input) {
                    // Only update if it's still the default or previous secondary color
                    const currentValue = input.value.toLowerCase();
                    const previousSecondary = input.getAttribute('data-default-color') || '#4C75A3';
                    if (currentValue === previousSecondary.toLowerCase() || currentValue === '#007bff') {
                      input.value = newSecondaryColor;
                      input.setAttribute('data-default-color', newSecondaryColor);
                    }
                  });
                });
              }
              
              // Set initial default color on first website input
              const firstWebsiteColor = document.getElementById('website_color_0');
              if (firstWebsiteColor) {
                const secondaryColor = getSecondaryColor();
                firstWebsiteColor.value = secondaryColor;
                firstWebsiteColor.setAttribute('data-default-color', secondaryColor);
              }
              
              // Plan limits are set in a separate script tag above
              // maxWebsites and maxVideos are available in global scope
              
              if (addWebsiteBtn && websitesContainer) {
              addWebsiteBtn.addEventListener("click", function() {
                  // Get current count of websites (including the initial one)
                  const currentWebsiteCount = websitesContainer.querySelectorAll('.website-item').length;
                  
                  // Check limit (only if maxWebsites is not -1)
                  if (maxWebsites !== -1 && currentWebsiteCount >= maxWebsites) {
                      showLimitNotification('You have reached the maximum limit of ' + maxWebsites + ' website links for your plan. Please upgrade your subscription to add more websites.');
                      return;
                  }
                  
                  const secondaryColor = getSecondaryColor();
                const websiteItem = document.createElement("div");
                websiteItem.className = "website-item mb-3 p-3 border rounded";
                  const websiteIndex = websitesContainer.querySelectorAll('.website-item').length;
                websiteItem.innerHTML = 
                  '<div class="row">' +
                    '<div class="form-group col-md-4">' +
                      '<label>Website URL</label>' +
                      '<input type="url" name="website_url[]" class="form-control" placeholder="https://example.com"/>' +
                    '</div>' +
                    '<div class="form-group col-md-4">' +
                      '<label>Website Name/Label</label>' +
                      '<input type="text" name="website_name[]" class="form-control" placeholder="My Portfolio"/>' +
                    '</div>' +
                    '<div class="form-group col-md-3">' +
                      '<label>Button Color</label>' +
                        '<input type="color" name="website_color[]" class="form-control form-control-color" id="website_color_' + websiteIndex + '" value="' + secondaryColor + '" data-default-color="' + secondaryColor + '"/>' +
                        '<small class="form-text text-muted" style="font-size: 0.75rem;">Defaults to Secondary Color</small>' +
                    '</div>' +
                    '<div class="form-group col-md-1 d-flex align-items-end">' +
                      '<button type="button" class="btn btn-danger btn-sm remove-website">' +
                        '<i class="fa fa-trash"></i>' +
                      '</button>' +
                    '</div>' +
                  '</div>';
                websitesContainer.appendChild(websiteItem);
                  if (typeof updateRemoveButtons === 'function') {
                updateRemoveButtons();
                  }
              });
              }

              // Videos functionality
              const videosContainer = document.getElementById("videos-container");
              const addVideoBtn = document.getElementById("add-video");
              
              addVideoBtn.addEventListener("click", function() {
                  // Get current count of videos (including the initial one)
                  const currentVideoCount = videosContainer.querySelectorAll('.video-item').length;
                  
                  // Check limit (only if maxVideos is not -1)
                  if (maxVideos !== -1 && currentVideoCount >= maxVideos) {
                      showLimitNotification('You have reached the maximum limit of ' + maxVideos + ' video(s) for your plan. Please upgrade your subscription to add more videos.');
                      return;
                  }
                  
                const videoItem = document.createElement("div");
                videoItem.className = "video-item mb-3 p-3 border rounded";
                videoItem.innerHTML = 
                  '<div class="row">' +
                    '<div class="form-group col-md-6">' +
                      '<label>Video URL</label>' +
                      '<input type="url" name="video_url[]" class="form-control" placeholder="https://www.youtube.com/watch?v=..."/>' +
                    '</div>' +
                    '<div class="form-group col-md-5">' +
                      '<label>Video Name/Label</label>' +
                      '<input type="text" name="video_name[]" class="form-control" placeholder="My Introduction Video"/>' +
                    '</div>' +
                    '<div class="form-group col-md-1 d-flex align-items-end">' +
                      '<button type="button" class="btn btn-danger btn-sm remove-video">' +
                        '<i class="fa fa-trash"></i>' +
                      '</button>' +
                    '</div>' +
                  '</div>';
                videosContainer.appendChild(videoItem);
                updateRemoveButtons();
              });

              // Remove buttons functionality
              function updateRemoveButtons() {
                // Update website remove buttons
                const websiteItems = websitesContainer.querySelectorAll(".website-item");
                websiteItems.forEach((item, index) => {
                  const removeBtn = item.querySelector(".remove-website");
                  if (websiteItems.length > 1) {
                    removeBtn.style.display = "block";
                  } else {
                    removeBtn.style.display = "none";
                  }
                });

                // Update video remove buttons
                const videoItems = videosContainer.querySelectorAll(".video-item");
                videoItems.forEach((item, index) => {
                  const removeBtn = item.querySelector(".remove-video");
                  if (videoItems.length > 1) {
                    removeBtn.style.display = "block";
                  } else {
                    removeBtn.style.display = "none";
                  }
                });
              }

              // Event delegation for remove buttons
              websitesContainer.addEventListener("click", function(e) {
                if (e.target.closest(".remove-website")) {
                  e.target.closest(".website-item").remove();
                  updateRemoveButtons();
                }
              });

              videosContainer.addEventListener("click", function(e) {
                if (e.target.closest(".remove-video")) {
                  e.target.closest(".video-item").remove();
                  updateRemoveButtons();
                }
              });

              // Initialize remove buttons
              updateRemoveButtons();
              
              // Step navigation functions
              function showStep(step) {
                document.querySelectorAll('.form-section').forEach(section => {
                  section.classList.remove('active');
                });
                document.querySelector('[data-step="' + step + '"]').classList.add('active');
                currentStep = step;
                updateProgress();
                updateStepIndicators();
                
                // Show/hide preview column
                const previewColumn = document.getElementById('preview-column');
                if (previewColumn) {
                  if (step === 8 || step === 1) {
                    previewColumn.classList.remove('d-none');
                    // Update preview when step 1 or 8 is shown
                    const templateInput = document.getElementById('selected_template');
                    const selectedTemplate = templateInput ? templateInput.value || 'modern' : 'modern';
                    if (typeof updateTemplatePreview === 'function') {
                      // Small delay to ensure form is ready
                      setTimeout(function() {
                        updateTemplatePreview(selectedTemplate);
                      }, 300);
                    }
                  } else {
                    previewColumn.classList.add('d-none');
                  }
                }
              }
              
              function updateStepIndicators() {
                // Add completed class to previous steps
                for (let i = 1; i < currentStep; i++) {
                  const stepSection = document.querySelector('[data-step="' + i + '"]');
                  if (stepSection) {
                    stepSection.classList.add('completed');
                  }
                }
                
                // Remove completed class from current and future steps
                for (let i = currentStep; i <= totalSteps; i++) {
                  const stepSection = document.querySelector('[data-step="' + i + '"]');
                  if (stepSection) {
                    stepSection.classList.remove('completed');
                  }
                }
              }
              
              function updateProgress() {
                const progress = (currentStep / totalSteps) * 100;
                progressBar.style.width = progress + '%';
                progressBar.setAttribute('aria-valuenow', progress);
              }
              
              function validateStep(step) {
                const section = document.querySelector('[data-step="' + step + '"]');
                const requiredFields = section.querySelectorAll('[required]');
                let isValid = true;
                let errorMessages = [];
                
                // Clear previous validation states
                requiredFields.forEach(field => {
                  field.classList.remove('is-invalid', 'is-valid');
                });
                
                // Validate each required field
                requiredFields.forEach(field => {
                  if (!field.value.trim()) {
                    field.classList.add('is-invalid');
                    isValid = false;
                    
                    // Get field label for error message
                    const label = field.closest('.form-group').querySelector('label');
                    const fieldName = label ? label.textContent.replace('*', '').trim() : 'This field';
                    errorMessages.push(fieldName + ' is required');
                  } else {
                    field.classList.add('is-valid');
                  }
                });
                
                // Special validation for email field
                const emailField = section.querySelector('input[type="email"]');
                if (emailField && emailField.value.trim()) {
                  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                  if (!emailRegex.test(emailField.value.trim())) {
                    emailField.classList.add('is-invalid');
                    isValid = false;
                    errorMessages.push('Please enter a valid email address');
                  }
                }
                
                // Special validation for website slug
                const slugField = section.querySelector('input[name="website_slug"]');
                if (slugField && slugField.value.trim()) {
                  const slugRegex = /^[a-zA-Z0-9-]+$/;
                  if (!slugRegex.test(slugField.value.trim())) {
                    slugField.classList.add('is-invalid');
                    isValid = false;
                    errorMessages.push('vCard URL can only contain letters, numbers, and hyphens');
                  }
                }
                
                // Show error message if validation fails
                if (!isValid) {
                  showStepError(errorMessages.join(', '));
                } else {
                  hideStepError();
                }
                
                return isValid;
              }
              
              function showStepError(message) {
                // Remove existing error alert
                const existingAlert = document.querySelector('.step-error-alert');
                if (existingAlert) {
                  existingAlert.remove();
                }
                
                // Create new error alert
                const alertDiv = document.createElement('div');
                alertDiv.className = 'alert alert-danger step-error-alert mt-3';
                alertDiv.innerHTML = 
                  '<i class="fa fa-exclamation-triangle me-2"></i>' +
                  '<strong>Please fix the following errors:</strong> ' + message;
                
                // Insert after the current step's card
                const currentSection = document.querySelector('[data-step="' + currentStep + '"]');
                const card = currentSection.querySelector('.card');
                card.parentNode.insertBefore(alertDiv, card.nextSibling);
                
                // Scroll to the error
                alertDiv.scrollIntoView({ behavior: 'smooth', block: 'center' });
              }
              
              function hideStepError() {
                const existingAlert = document.querySelector('.step-error-alert');
                if (existingAlert) {
                  existingAlert.remove();
                }
              }
              
              // Save form data to localStorage
              function saveFormData() {
                const formData = new FormData(form);
                const data = {};
                for (let [key, value] of formData.entries()) {
                  if (key !== 'csrf_token' && key !== 'image_url' && key !== 'qr_logo') {
                    data[key] = value;
                  }
                }
                localStorage.setItem('vcard_form_data', JSON.stringify(data));
              }
              
              // Load form data from localStorage
              function loadFormData() {
                const savedData = localStorage.getItem('vcard_form_data');
                if (savedData) {
                  try {
                    const data = JSON.parse(savedData);
                    Object.keys(data).forEach(key => {
                      const field = form.querySelector('[name="' + key + '"]');
                      if (field && field.type !== 'file') {
                        field.value = data[key];
                        // Trigger validation styling
                        if (field.hasAttribute('required') && field.value.trim()) {
                          field.classList.add('is-valid');
                        }
                      }
                    });
                  } catch (e) {
                    // Failed to load saved form data; ignore silently in production
                  }
                }
              }
              
              // Clear saved form data
              function clearFormData() {
                localStorage.removeItem('vcard_form_data');
              }
              
              // Auto-advance on field completion
              document.querySelectorAll('input, select, textarea').forEach(field => {
                field.addEventListener('blur', function() {
                  if (this.hasAttribute('required') && this.value.trim()) {
                    this.classList.remove('is-invalid');
                    this.classList.add('is-valid');
                  }
                  saveFormData(); // Save data on blur
                });
                
                field.addEventListener('input', function() {
                  if (this.classList.contains('is-invalid') && this.value.trim()) {
                    this.classList.remove('is-invalid');
                    this.classList.add('is-valid');
                  }
                  saveFormData(); // Save data on input
                });
              });
              
              // Navigation functions
              function nextStep() {
                if (validateStep(currentStep)) {
                  if (currentStep < totalSteps) {
                    const nextStepNum = currentStep + 1;
                    showStep(nextStepNum);
                    // Auto-fill slug when moving to step 2 if name is filled and slug is empty
                    if (nextStepNum === 2) {
                      setTimeout(() => {
                        // Look up elements dynamically to avoid scope issues
                        const nameField = document.getElementById('name_input');
                        const slugFieldEl = document.querySelector('input[name="website_slug"]');
                        if (nameField && slugFieldEl) {
                          const currentName = nameField.value.trim();
                          if (currentName && !slugFieldEl.value) {
                            // Check if slug was manually edited by checking if it has a value that doesn't match the name
                            const nameSlug = currentName.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
                            const currentSlug = slugFieldEl.value.toLowerCase();
                            // Only auto-fill if slug is empty or matches the name pattern (not manually edited)
                            if (!currentSlug || currentSlug === nameSlug || currentSlug.startsWith(nameSlug + '-')) {
                              // Trigger auto-fill by calling the function if it exists, or dispatch input event
                              if (typeof autoFillSlugFromName === 'function') {
                                autoFillSlugFromName();
                              } else {
                                // Fallback: trigger input event on name field to trigger auto-fill
                                nameField.dispatchEvent(new Event('input', { bubbles: true }));
                              }
                            }
                          }
                        }
                      }, 300);
                    }
                  }
                }
              }
              
              function prevStep() {
                if (currentStep > 1) {
                  showStep(currentStep - 1);
                }
              }
              
              // Add navigation buttons to each step
              function addNavigationButtons() {
                document.querySelectorAll('.form-section').forEach((section, index) => {
                  const stepNumber = index + 1;
                  const cardBody = section.querySelector('.card-body');
                  
                  if (cardBody) {
                    const navDiv = document.createElement('div');
                    navDiv.className = 'd-flex justify-content-between mt-4';
                    
                    if (stepNumber > 1) {
                      const prevBtn = document.createElement('button');
                      prevBtn.type = 'button';
                      prevBtn.className = 'btn btn-outline-secondary';
                      const prevIcon = document.createElement('i');
                      prevIcon.className = 'fa fa-arrow-left me-2';
                      prevBtn.appendChild(prevIcon);
                      prevBtn.appendChild(document.createTextNode('Previous'));
                      prevBtn.onclick = prevStep;
                      navDiv.appendChild(prevBtn);
                    } else {
                      navDiv.appendChild(document.createElement('div'));
                    }
                    
                    if (stepNumber < totalSteps) {
                      const nextBtn = document.createElement('button');
                      nextBtn.type = 'button';
                      nextBtn.className = 'btn btn-primary';
                      nextBtn.appendChild(document.createTextNode('Next'));
                      const nextIcon = document.createElement('i');
                      nextIcon.className = 'fa fa-arrow-right ms-2';
                      nextBtn.appendChild(nextIcon);
                      nextBtn.onclick = nextStep;
                      navDiv.appendChild(nextBtn);
                    } else {
                      // On last step, show a button that triggers form submission
                      const submitBtn = document.createElement('button');
                      submitBtn.type = 'button';
                      submitBtn.className = 'btn btn-success btn-lg';
                      const submitIcon = document.createElement('i');
                      submitIcon.className = 'fa fa-rocket me-2';
                      submitBtn.appendChild(submitIcon);
                      submitBtn.appendChild(document.createTextNode('Create Card'));
                      submitBtn.onclick = function() {
                        // Trigger form submission
                        form.dispatchEvent(new Event('submit'));
                      };
                      navDiv.appendChild(submitBtn);
                    }
                    
                    cardBody.appendChild(navDiv);
                  }
                });
              }
              
              // Initialize navigation buttons
              addNavigationButtons();
              
              // Template selection functionality
              const templateOptions = document.querySelectorAll('.template-option');
              const selectedTemplateInput = document.getElementById('selected_template');
              
              // Function to update template preview by generating actual website
              let previewTimeout = null;
              function updateTemplatePreview(template) {
                const previewIframe = document.getElementById('vcard-preview-iframe');
                const loadingIndicator = document.getElementById('preview-loading');
                if (!previewIframe) return;
                
                // Show loading indicator
                if (loadingIndicator) {
                  loadingIndicator.style.display = 'block';
                }
                
                // Debounce preview updates (wait 500ms after last change)
                if (previewTimeout) {
                  clearTimeout(previewTimeout);
                }
                
                previewTimeout = setTimeout(function() {
                  // Get form data
                  const formData = new FormData(form);
                  const data = {};
                  
                  // Collect all form fields
                  for (let [key, value] of formData.entries()) {
                    if (key !== 'csrf_token' && key !== 'image_url' && key !== 'banner_image' && key !== 'qr_logo') {
                      // Handle array fields
                      if (key.endsWith('[]')) {
                        const fieldName = key.slice(0, -2);
                        if (!data[fieldName]) {
                          data[fieldName] = [];
                        }
                        data[fieldName].push(value);
                      } else {
                        data[key] = value;
                      }
                    }
                  }
                  
                  // Get checkbox values directly
                  const showFormCheckbox = document.getElementById('show_form_yes');
                  if (showFormCheckbox) {
                    data.show_form = showFormCheckbox.checked;
                  }
                  
                  const notifyCheckbox = document.getElementById('notify_on_new_lead_yes');
                  if (notifyCheckbox) {
                    data.notify_on_new_lead = notifyCheckbox.checked;
                  }
                  
                  const introEmailCheckbox = document.getElementById('intro_email_enabled_yes');
                  if (introEmailCheckbox) {
                    data.intro_email_enabled = introEmailCheckbox.checked;
                  }
                  
                  const leadbackCheckbox = document.getElementById('enable_instant_leadback_yes');
                  if (leadbackCheckbox) {
                    data.enable_instant_leadback = leadbackCheckbox.checked;
                  }
                  
                  const leadbackEmailCheckbox = document.getElementById('leadback_send_email_yes');
                  if (leadbackEmailCheckbox) {
                    data.leadback_send_email = leadbackEmailCheckbox.checked;
                  }
                  
                  const leadbackMessagingCheckbox = document.getElementById('leadback_enable_messaging_yes');
                  if (leadbackMessagingCheckbox) {
                    data.leadback_enable_messaging = leadbackMessagingCheckbox.checked;
                  }
                  
                  const showReviewsCheckbox = document.getElementById('show_reviews_yes');
                  if (showReviewsCheckbox) {
                    data.show_reviews = showReviewsCheckbox.checked;
                  }
                  
                  // Collect leadback channels
                  const leadbackChannels = [];
                  document.querySelectorAll('input[name="leadback_channels[]"]:checked').forEach(function(checkbox) {
                    leadbackChannels.push(checkbox.value);
                  });
                  if (leadbackChannels.length > 0) {
                    data.leadback_channels = leadbackChannels;
                  }
                  
                  // Ensure template is set
                  data.website_template = template || data.website_template || 'modern';
                  
                  // Handle image files if present
                  const imageFile = form.querySelector('input[name="image_url"]').files[0];
                  const bannerFile = form.querySelector('input[name="banner_image"]').files[0];
                  
                  let filesToProcess = 0;
                  let filesProcessed = 0;
                  
                  if (imageFile) filesToProcess++;
                  if (bannerFile) filesToProcess++;
                  
                  const processFiles = function() {
                    filesProcessed++;
                    if (filesProcessed >= filesToProcess) {
                      sendPreviewRequest(data, previewIframe, loadingIndicator);
                    }
                  };
                  
                  if (imageFile) {
                    const reader = new FileReader();
                    reader.onload = function(e) {
                      data.image_base64 = e.target.result.split(',')[1];
                      processFiles();
                    };
                    reader.readAsDataURL(imageFile);
                  } else {
                    processFiles();
                  }
                  
                  if (bannerFile) {
                    const reader = new FileReader();
                    reader.onload = function(e) {
