                console.log('generateUniqueSlug: Checking base slug:', baseSlug);
                
                // First check if the base slug is available
                const result = await checkSlugAvailability(baseSlug);
                console.log('generateUniqueSlug: Base slug check result:', result);
                
                if (result && result.available === true) {
                  console.log('generateUniqueSlug: Base slug is available, returning:', baseSlug);
                  return baseSlug;
                }
                
                // If not available and we have a suggestion, use it
                if (result && result.suggestion) {
                  console.log('generateUniqueSlug: Using backend suggestion:', result.suggestion);
                  return result.suggestion;
                }
                
                // Fallback: try appending numbers manually (but limit to reasonable number)
                // This should rarely happen if backend is working correctly
                console.warn('generateUniqueSlug: No suggestion from backend, trying sequential numbers');
                let counter = 2;
                let uniqueSlug = `${baseSlug}-${counter}`;
                
                while (counter < 20) {  // Limit to 20 attempts instead of 100
                  const checkResult = await checkSlugAvailability(uniqueSlug);
                  console.log(`generateUniqueSlug: Checking ${uniqueSlug}, result:`, checkResult);
                  if (checkResult && checkResult.available === true) {
                    console.log('generateUniqueSlug: Found available slug:', uniqueSlug);
