                    // Only set if it's not the fallback "-20" value
                    slugField.value = uniqueSlug;
                    lastGeneratedName = currentName;
                    slugField.classList.add('is-valid');
                    slugField.classList.remove('is-invalid');
                  } else if (uniqueSlug === baseSlug) {
                    // Base slug is available - use it
                    slugField.value = uniqueSlug;
                    lastGeneratedName = currentName;
                    slugField.classList.add('is-valid');
                    slugField.classList.remove('is-invalid');
